         <!-- Click To Redirect Option -->\n            <smc-option class=\"smc-clickRedirect\">\n                <smc-input-group>\n                    <span class=\"smc-button smc-animated smc-fadeInRight smc-animDelay10\" data-edits=\"text10\" data-changes=\".smc-button|font-size,background-color,color\">{text10}</span>\n                </smc-input-group>\n            </smc-option>\n\n            <!-- Email to GiftCloud Option -->\n            <smc-option class=\"smc-emailToGiftCloud\">\n                <smc-input-group><input class=\"smc-input smc-animated smc-fadeInLeft smc-animDelay8\" name=\"email\" autocomplete=\"smc-autocomplete\" data-required=\"true\" data-verify=\"email\" placeholder=\"{text13}\" type=\"text\"></smc-input-group>\n                <smc-reveal class=\"smc-animated smc-bounceInUp smc-animDelay12\">\n                    <smc-cover data-edits=\"text12\" data-changes=\".smc-emailToReveal smc-cover|font-size,background-color,color\">{text12}</smc-cover>\n                </smc-reveal>    \n            </smc-option>\n            \n\t\t\t<!-- Request Notifications -->\n\t\t\t<smc-option class=\"smc-requestNotifications\">\n\t\t\t   <smc-input-group>\n\t\t\t\t   <span class=\"smc-button smc-animated smc-fadeInRight smc-animDelay10\" data-close-timeout=\"2000\">Enable Notifications</span>\n\t\t\t   </smc-input-group>\n\t\t\t   <smc-agree-yes class=\"smc-animated smc-fadeIn\">Thanks for enabling</smc-agree-yes>\n\t\t\t   <smc-agree-no class=\"smc-animated smc-fadeIn\">Ok no problem</smc-agree-no>\n\t\t\t</smc-option>\n\n            <!-- Dynamic Form Example -->\n            <smc-option class=\"smc-dynamicForm\">\n                <smc-input-group><input class=\"smc-input smc-animated smc-fadeInLeft smc-animDelay6\" data-required=\"true\" autocomplete=\"smc-autocomplete\" name=\"fullname\" placeholder=\"ENTER YOUR NAME\" type=\"text\"></smc-input-group>\n                <smc-input-group><input class=\"smc-input smc-animated smc-fadeInLeft smc-animDelay7\" data-required=\"true\" autocomplete=\"smc-autocomplete\" name=\"address\" placeholder=\"YOUR ADDRESS\" type=\"text\"></smc-input-group>\n                <smc-input-group><input class=\"smc-input smc-animated smc-fadeInLeft smc-animDelay8\" data-required=\"true\" autocomplete=\"smc-autocomplete\" data-verify=\"email\" name=\"email\" placeholder=\"YOUR EMAIL\" type=\"text\"></smc-input-group>\n                <smc-input-group>\n                    <div class=\"smc-animated smc-fadeInLeft smc-animDelay9\">\n                        <label><input type=\"radio\" name=\"sex\" data-required=\"true\" value=\"male\">Male</label>\n                        <label><input type=\"radio\" name=\"sex\" data-required=\"true\" value=\"female\">Female</label>\n                        <label><input type=\"radio\" name=\"sex\" data-required=\"true\" value=\"other\">Other</label>\n                    </div>\n                </smc-input-group>\n\n                <!-- Cool Checkboxes -->\n                <smc-cool-checkboxes class=\"smc-animated smc-fadeInRight smc-animDelay10\">\n                    <smc-input-group data-edits=\"cool-checkbox\" data-eq=\"1\">\n                        <label>\n                            <input type=\"checkbox\" name=\"smc-agree1\" value=\"yes\" data-required=\"false\">\n                            <smc-ccb-tick></smc-ccb-tick>\n                            <smc-ccb-text>I agree to the <smc-show-terms data-id=\"terms1\"> terms </smc-show-terms></smc-ccb-text>\n                        </label>\n                    </smc-input-group>\n                    <smc-input-group data-edits=\"cool-checkbox\" data-eq=\"2\">\n                        <label>\n                    \t    <input type=\"checkbox\" name=\"smc-agree2\" value=\"yes\" data-required=\"false\">\n                    \t    <smc-ccb-tick></smc-ccb-tick>\n                    \t    <smc-ccb-text>I also agree to the <smc-show-terms data-id=\"terms2\">secondary terms</smc-show-terms> as well</smc-ccb-text>\n                        </label>\n                    </smc-input-group>\n                </smc-cool-checkboxes>\n                <!-- End Cool Checkboxes -->\n                <input class=\"smc-button smc-animated smc-fadeInRight smc-animDelay10\" value=\"SUBMIT FORM\" type=\"submit\">\n            </smc-option>\n\n            <!-- Data Consent Example - data-hidden-id=\"\" - Important to copy the new hidden inputs with copied values -->\n            <smc-option class=\"smc-dataConsent\">\n                <smc-input-group>\n                    <input class=\"smc-input smc-animated smc-fadeInLeft smc-animDelay8\" data-required=\"true\" data-verify=\"email\" name=\"email\" data-hidden-id=\"smc-consented-email\" placeholder=\"ENTER YOUR EMAIL\" type=\"text\">\n                </smc-input-group>\n                <!-- Cool Checkboxes -->\n                <smc-cool-checkboxes class=\"smc-animated smc-fadeInRight smc-animDelay10\">\n                    <smc-input-group data-edits=\"cool-checkbox\" data-eq=\"3\">\n                        <label>\n                            <input type=\"checkbox\" name=\"smc-agree1\" value=\"yes\" data-required=\"true\">\n                            <smc-ccb-tick></smc-ccb-tick>\n                            <smc-ccb-text>I agree to the <smc-show-terms data-id=\"terms1\"> terms </smc-show-terms></smc-ccb-text>\n                        </label>\n                    </smc-input-group>\n                    <smc-input-group data-edits=\"cool-checkbox\" data-eq=\"4\">\n                        <label>\n                            <input type=\"checkbox\" name=\"smc-agree2\" value=\"yes\" data-required=\"true\">\n                            <smc-ccb-tick></smc-ccb-tick>\n                            <smc-ccb-text>I also agree to the <smc-show-terms data-id=\"terms2\">secondary terms</smc-show-terms> as well</smc-ccb-text>\n                        </label>\n                    </smc-input-group>\n                </smc-cool-checkboxes>\n                <!-- End Cool Checkboxes -->\n                <input class=\"smc-button smc-animated smc-fadeInRight smc-animDelay10\" value=\"Save My Basket\" type=\"submit\">\n            </smc-option>\n\n            <!-- Closers (Both Need) -->\n            <smc-long-close class=\"smc-animated smc-fadeInUp smc-animDelay14\" data-engage-class=\"smc-engaged\">\n                <a data-close-type=\"long_close\" class=\"smc-link smc-closer\" href=\"#rdl\" data-engage-text=\"{text11}\" data-edits=\"text7,text11\" data-changes=\"smc-long-close a.smc-link|font-size,color,margin-top,margin-bottom\">{text7}</a>\n                <!-- Note - Redirect Link gets automatically rewritten, once clicked on the data-engage text and classes are applied -->\n            </smc-long-close>\n\n            <smc-close class=\"smc-animated smc-fadeInRight smc-animDelay4 smc-closer\">\n                <a data-close-type=\"x_close\" class=\"smc-link\" href=\"#rdl\">✕</a><!-- Note - Redirect Link gets automatically rewritten -->\n            </smc-close>\n            \n\n            <!-- Success Message -->\n            <smc-success-message class=\"smc-animated smc-fadeIn\">\n                <smc-success-message-inner class=\"smc-animated smc-bounceInDown smc-animDelay1\">\n                    Perfect thank you!\n                    <smc-success-close>X</smc-success-close>\n                </smc-success-message-inner>    \n            </smc-success-message>\n            \n            <!-- CSS Loader -->\n            <smc-loader-bg data-theme=\"white\"><!-- white, black-->\n                <smc-loader-single></smc-loader-single><!-- single, double, pulse -->\n            </smc-loader-bg>\n \n            <!-- Copy to Clipboard Success Message -->\n            <smc-cp-msg>\"{vc}\" has been copied to the clipboard</smc-cp-msg>\n\n        </smc-overlay-inner>\n        <smc-shake-msg>\n            <i class=\"fa fa-mobile\" aria-hidden=\"true\"></i><br>\n            Shake To Reaveal Voucher\n        </smc-shake-msg>\n    </smc-overlay-outer>\n    \n    <!-- Safe close - Used when Autoscaling is turned on -->\n    <smc-close-safe class=\"smc-closer\">\n    \t<a data-close-type=\"x_close\" class=\"smc-link\" href=\"#rdl\">[close]</a><!-- Note - Redirect Link gets automatically rewritten -->\n    </smc-close-safe>\n</smc-bg>\n\n<!-- SmarterBar -->\n<smc-bar class=\"smc-animated smc-fadeInDown\">\n    <smc-bar-close>X</smc-bar-close>\n    <smc-bar-text>{smarterbar}</smc-bar-text>\n    <smc-handle>\n        <span class=\"smc-bar1\"></span>\n        <span class=\"smc-bar2\"></span>\n        <span class=\"smc-bar3\"></span>\n    </smc-handle>\n</smc-bar>\n\n<!-- Final Mesage Box -->\n<smc-final-message class=\"smc-animated smc-fadeInDown\">Thanks... your code is: {vc}<smc-final-message-close>X</smc-final-message-close></smc-final-message>","opt":""},"PR0009":{"css":"@import url('https://fonts.googleapis.com/css?family=Montserrat:400,500,600,700');\n\nsmc-overlay-inner {\n\t--smc-cardBkg: #ffffff;\n\t--smc-textColour: #19124f;\n\t--smc-textColour2: #000000;\n\t--smc-accent: #000000;\n\t--smc-btnBkg: #000000;\n\t--smc-btnText: #ffffff;\n\t--smc-btnBorderRadius: 4px;\n\t--smc-frameBorderRadius: 2px;\n\t--smc-btnFontSize: 14px;\n\t--smc-btnPadding: 10px;\n}\n\nsmc-bg * {\n\tfont-family: 'Montserrat', sans-serif;\n}\n\nsmc-bg {\n\tbackground-color: transparent;\n\tpointer-events: none;\n}\n\nsmc-overlay-outer {\n\tposition: absolute;\n\tbottom: 10px;\n\tright: 10px;\n}\n\nsmc-overlay-inner {\n\tbackground-color: transparent;\n\tbackground-size: cover;\n\twidth: 550px;\n\tmin-height: 160px;\n\tborder-radius: var(--smc-frameBorderRadius);\n\tpointer-events: all;\n\tpadding: 0;\n\tmargin: auto;\n}\n.smc-text1 {\n\tposition: absolute;\n\tleft: 0;\n\tright: 0;\n\tmargin: auto;\n\ttext-align: center;\n\ttop: -40px;\n\tbackground: var(--smc-accent);\n\tpadding: 10px;\n\tcolor: #fff;\n\twidth: 60%;\n\tz-index: -1;\n\tpadding-bottom: 30px;\n\tpadding-top: 13px;\n\tborder-radius: 10px;\n}\nsmc-cart {\n\tposition: absolute;\n\tbottom: 0;\n\tleft: 0;\n\twidth: 100%;\n\theight: 100%;\n\tpadding: 2px;\n\tdisplay: flex;\n\tflex-direction: column;\n\tjustify-content: center;\n\toverflow: hidden;\n\tborder-radius: 5px;\n\talign-items: flex-start;\n}\n\nsmc-product {\n\talign-self: center;\n\theight: 100%;\n\tdisplay: flex !important;\n\tflex-direction: row;\n\twidth: 100%;\n\tbackground-color: var(--smc-cardBkg);\n\tmargin: 5px auto;\n}\n\nsmc-left,\nsmc-right {\n\tdisplay: flex;\n\talign-items: center;\n\tjustify-content: center;\n\twidth: 20%;\n\tflex-direction: column;\n}\n\nsmc-right {\n\tdisplay: flex;\n\tflex-direction: row;\n\tpadding: 0;\n\twidth: 100%;\n\tjustify-content: space-between;\n}\n\nsmc-product-img,\nsmc-product-name,\nsmc-product-rating,\nsmc-prices,\nsmc-product-desc {\n\tdisplay: block;\n\tmargin: 5px auto;\n\tfont-weight: 300;\n\tfont-size: 14px;\n\tcolor: var(--smc-textColour);\n\twidth: 100%;\n\ttext-align: left;\n}\n\nsmc-product-img {\n\tmax-width: 70px;\n\tmax-height: 70px;\n\tdisplay: flex;\n\talign-items: center;\n\toverflow: hidden;\n\tmargin: auto;\n}\n\nsmc-product-img img {\n\twidth: 100%;\n\theight: auto;\n}\n\nsmc-product-name {\n\tfont-size: 14px;\n\ttext-overflow: ellipsis;\n\tcolor: var(--smc-textColour2);\n\toverflow: hidden;\n\tdisplay: -webkit-box;\n\t-webkit-line-clamp: 2;\n\t-webkit-box-orient: vertical;\n\tfont-weight: 600;\n\tline-height: 1.2;\n\twidth: 240px;\n}\n\n.smc-button-new {\n\twidth: 190px;\n\tmargin: 0;\n\tpadding: var(--smc-btnPadding);\n\tborder-radius: var(--smc-btnBorderRadius);\n\tfont-size: var(--smc-btnFontSize);\n\tcolor: var(--smc-btnText);\n\tbackground-color: var(--smc-btnBkg);\n\tfont-weight: 500;\n\theight: 70%;\n\tdisplay: flex;\n\tflex-direction: row;\n\tjustify-content: space-around;\n\tmargin-right: 10px;\n\talign-items: center;\n\tcursor: pointer;\n}\n\n.smc-button-new span {\n\tdisplay: flex;\n\tflex-direction: column;\n\tjustify-content: center;\n}\n\nsmc-product-price {\n\tfont-weight: 400;\n\tfont-size: 14px;\n\tcolor: #fff;\n}\n\nsmc-close {\n\ttop: -5px;\n\tleft: -5px;\n\tbackground: #fff;\n\twidth: 20px;\n\theight: 20px;\n}\n\nsmc-close a.smc-link {\n\tcolor: var(--smc-textColour2);\n\tdisplay: flex;\n\tjustify-content: center;\n\talign-items: center;\n\tfont-size: 11px;\n}\nsmc-long-close{\n\tposition: absolute;\n\tbottom: -30px;\n}\n","html":"<!-- Overlay V4 Template -->\n<smc-bg class=\"smc-animated smc-fadeIn\">\n  <smc-overlay-outer class=\"smc-animated smc-bounceInDown smc-animDelay2\">\n    <!--  data-animout=\"smc-bounceOutLeft\" -->\n    <smc-overlay-inner\n      class=\"smc_clearfix\"\n      data-bgtheme=\"dark\"\n      data-changes=\"smc-overlay-inner|width,background-image,background-color\"\n      data-edits=\"content6\"\n      ><!-- If the background is dark use this option -->\n\n      <smc-cart>\n        <smc-product>\n          <smc-left>\n            <smc-product-img\n              ><img\n                src=\"https://cdn6.hughes.co.uk/thumbnail/a6/96/0d/1715677657/LG-US70TY-C_800x800.jpg\"\n            /></smc-product-img>\n          </smc-left>\n          <smc-right>\n            <smc-product-name\n              >LG US70TY 3.1.3 Channel Soundbar with Wireless\n              Subwoofer</smc-product-name\n            >\n            <span class=\"smc-button-new\"\n              >Add to basket<smc-product-price>£479.00</smc-product-price></span\n            >\n          </smc-right>\n        </smc-product>\n\n        <smc-product>\n          <smc-left>\n            <smc-product-img\n              ><img\n                src=\"https://cdn6.hughes.co.uk/thumbnail/12/d1/78/1678892801/SUS-VMF720-B2_800x800.jpg\"\n            /></smc-product-img>\n          </smc-left>\n          <smc-right>\n            <smc-product-name\n              >Sanus VMF720-B2 Wallmount Bracket 32\"-65\",\n              black</smc-product-name\n            >\n            <span class=\"smc-button-new\"\n              >Add to basket<smc-product-price\n                >£104.99\n              </smc-product-price></span\n            >\n          </smc-right>\n        </smc-product>\n      </smc-cart>\n\n      <!-- Images - You can add as many as you like -->\n      <smc-img-outer>\n        <smc-img\n          class=\"smc-img1 smc-animated smc-bounceInDown smc-animDelay6\"\n          data-changes=\".smc-img1|margin-top,margin-bottom,image-upload\"\n          data-edits=\"content1\"\n          ><img src=\"{content1}\" alt=\"\"\n        /></smc-img>\n        <smc-img\n          class=\"smc-img2 smc-animated smc-bounceInRight smc-animDelay8\"\n          data-changes=\".smc-img2|margin-top,margin-bottom,image-upload\"\n          data-edits=\"content2\"\n          ><img src=\"{content2}\" alt=\"\"\n        /></smc-img>\n        <smc-img\n          class=\"smc-img3 smc-animated smc-bounceInRight smc-animDelay10\"\n          data-changes=\".smc-img3|margin-top,margin-bottom,image-upload\"\n          data-edits=\"content3\"\n          ><img src=\"{content3}\" alt=\"\"\n        /></smc-img>\n        <smc-img\n          class=\"smc-img4 smc-animated smc-bounceInRight smc-animDelay12\"\n          data-changes=\".smc-img4|margin-top,margin-bottom,image-upload\"\n          data-edits=\"content4\"\n          ><img src=\"{content4}\" alt=\"\"\n        /></smc-img>\n      </smc-img-outer>\n\n      <!-- Text Boxes - You can add as many as you like -->\n      <smc-text\n        class=\"smc-text1\"\n        data-edits=\"text1\"\n        data-changes=\".smc-text1|font-size,color,margin-top,margin-bottom\"\n      ></smc-text>\n      <smc-text-outer>\n        <smc-text\n          class=\"smc-text2 smc-animated smc-bounceInRight smc-animDelay6\"\n          data-edits=\"text2\"\n          data-changes=\".smc-text2|font-size,color,margin-top,margin-bottom\"\n        ></smc-text>\n        <smc-text\n          class=\"smc-text3 smc-animated smc-bounceInLeft smc-animDelay8\"\n          data-edits=\"text3\"\n          data-changes=\".smc-text3|font-size,color,margin-top,margin-bottom\"\n          >{text3}</smc-text\n        >\n        <smc-text\n          class=\"smc-text4 smc-animated smc-bounceInRight smc-animDelay10\"\n          data-edits=\"text4\"\n          data-changes=\".smc-text4|font-size,color,margin-top,margin-bottom\"\n          >{text4}</smc-text\n        >\n      </smc-text-outer>\n\n      <!-- Email Voucher Option -->\n      <smc-option class=\"smc-email\">\n        <smc-input-group\n          ><input\n            class=\"smc-input smc-animated smc-fadeInLeft smc-animDelay8\"\n            name=\"email\"\n            autocomplete=\"smc-autocomplete\"\n            data-required=\"true\"\n            data-verify=\"email\"\n            placeholder=\"ENTER YOUR EMAIL HERE\"\n            type=\"text\"\n        /></smc-input-group>\n        <smc-input-group\n          ><input\n            class=\"smc-button smc-animated smc-fadeInRight smc-animDelay10\"\n            value=\"Email Voucher\"\n            type=\"submit\"\n        /></smc-input-group>\n      </smc-option>\n\n      <!-- Click To Reveal Option -->\n      <smc-option class=\"smc-clickToReveal\">\n        <smc-reveal class=\"smc-animated smc-bounceInUp smc-animDelay12\">\n          <smc-cover\n            data-edits=\"text8\"\n            data-changes=\".smc-clickToReveal smc-cover|font-size,background-color,color\"\n            >{text8}</smc-cover\n          >\n          <smc-code>{vc}</smc-code>\n          <smc-cp data-clipboard-text=\"{vc-cp}\"></smc-cp>\n        </smc-reveal>\n      </smc-option>\n\n      <!-- Email To Reveal Option -->\n      <smc-option class=\"smc-emailToReveal\">\n        <smc-input-group\n          ><input\n            class=\"smc-input smc-animated smc-fadeInLeft smc-animDelay8\"\n            name=\"email\"\n            autocomplete=\"smc-autocomplete\"\n            data-required=\"true\"\n            data-verify=\"email\"\n            placeholder=\"{text13}\"\n            type=\"text\"\n        /></smc-input-group>\n        <smc-reveal class=\"smc-animated smc-bounceInUp smc-animDelay12\">\n          <smc-cover\n            data-edits=\"text9\"\n            data-changes=\".smc-emailToReveal smc-cover|font-size,background-color,color\"\n            >{text9}</smc-cover\n          >\n          <smc-code>{vc}</smc-code>\n          <smc-cp data-clipboard-text=\"{vc-cp}\"></smc-cp>\n        </smc-reveal>\n      </smc-option>\n\n      <!-- Uniqodo Email To Reveal Option -->\n      <smc-option class=\"smc-uniqodoEmailToReveal\">\n        <smc-input-group\n          ><input\n            class=\"smc-input smc-animated smc-fadeInLeft smc-animDelay8\"\n            name=\"email\"\n            autocomplete=\"smc-autocomplete\"\n            data-required=\"true\"\n            data-verify=\"email\"\n            placeholder=\"{text13}\"\n            type=\"text\"\n        /></smc-input-group>\n        <smc-reveal class=\"smc-animated smc-bounceInUp smc-animDelay12\">\n          <smc-cover\n            data-edits=\"text9\"\n            data-changes=\".smc-emailToReveal smc-cover|font-size,background-color,color\"\n            >{text9}</smc-cover\n          >\n          <smc-code>{vc}</smc-code>\n          <smc-cp data-clipboard-text=\"{vc-cp}\"></smc-cp>\n        </smc-reveal>\n      </smc-option>\n\n      <!-- Uniqodo Click To Reveal Option -->\n      <smc-option class=\"smc-uniqodoCodeReveal\">\n        <smc-reveal class=\"smc-animated smc-bounceInUp smc-animDelay12\">\n          <smc-cover\n            data-edits=\"text8\"\n            data-changes=\".smc-uniqodoCodeReveal smc-cover|font-size,background-color,color\"\n            >{text8}</smc-cover\n          >\n          <smc-code>{vc}</smc-code>\n          <smc-cp data-clipboard-text=\"{vc-cp}\"></smc-cp>\n        </smc-reveal>\n      </smc-option>\n\n      <!-- Click To Redirect Option -->\n      <smc-option class=\"smc-clickRedirect\">\n        <smc-input-group>\n          <!-- <span class=\"smc-button smc-animated smc-fadeInRight smc-animDelay10\" data-edits=\"text10\" data-changes=\".smc-button|font-size,background-color,color\">{text10}</span> -->\n        </smc-input-group>\n      </smc-option>\n\n      <!-- Email to GiftCloud Option -->\n      <smc-option class=\"smc-emailToGiftCloud\">\n        <smc-input-group\n          ><input\n            class=\"smc-input smc-animated smc-fadeInLeft smc-animDelay8\"\n            name=\"email\"\n            autocomplete=\"smc-autocomplete\"\n            data-required=\"true\"\n            data-verify=\"email\"\n            placeholder=\"{text13}\"\n            type=\"text\"\n        /></smc-input-group>\n        <smc-reveal class=\"smc-animated smc-bounceInUp smc-animDelay12\">\n          <smc-cover\n            data-edits=\"text12\"\n            data-changes=\".smc-emailToReveal smc-cover|font-size,background-color,color\"\n            >{text12}</smc-cover\n          >\n        </smc-reveal>\n      </smc-option>\n\n      <!-- Request Notifications -->\n      <smc-option class=\"smc-requestNotifications\">\n        <smc-input-group>\n          <span\n            class=\"smc-button smc-animated smc-fadeInRight smc-animDelay10\"\n            data-close-timeout=\"2000\"\n            >Enable Notifications</span\n          >\n        </smc-input-group>\n        <smc-agree-yes class=\"smc-animated smc-fadeIn\"\n          >Thanks for enabling</smc-agree-yes\n        >\n        <smc-agree-no class=\"smc-animated smc-fadeIn\"\n          >Ok no problem</smc-agree-no\n        >\n      </smc-option>\n\n      <!-- Dynamic Form Example -->\n      <smc-option class=\"smc-dynamicForm\">\n        <smc-input-group\n          ><input\n            class=\"smc-input smc-animated smc-fadeInLeft smc-animDelay6\"\n            data-required=\"true\"\n            autocomplete=\"smc-autocomplete\"\n            name=\"fullname\"\n            placeholder=\"ENTER YOUR NAME\"\n            type=\"text\"\n        /></smc-input-group>\n        <smc-input-group\n          ><input\n            class=\"smc-input smc-animated smc-fadeInLeft smc-animDelay7\"\n            data-required=\"true\"\n            autocomplete=\"smc-autocomplete\"\n            name=\"address\"\n            placeholder=\"YOUR ADDRESS\"\n            type=\"text\"\n        /></smc-input-group>\n        <smc-input-group\n          ><input\n            class=\"smc-input smc-animated smc-fadeInLeft smc-animDelay8\"\n            data-required=\"true\"\n            autocomplete=\"smc-autocomplete\"\n            data-verify=\"email\"\n            name=\"email\"\n            placeholder=\"YOUR EMAIL\"\n            type=\"text\"\n        /></smc-input-group>\n        <smc-input-group>\n          <div class=\"smc-animated smc-fadeInLeft smc-animDelay9\">\n            <label\n              ><input\n                type=\"radio\"\n                name=\"sex\"\n                data-required=\"true\"\n                value=\"male\"\n              />Male</label\n            >\n            <label\n              ><input\n                type=\"radio\"\n                name=\"sex\"\n                data-required=\"true\"\n                value=\"female\"\n              />Female</label\n            >\n            <label\n              ><input\n                type=\"radio\"\n                name=\"sex\"\n                data-required=\"true\"\n                value=\"other\"\n              />Other</label\n            >\n          </div>\n        </smc-input-group>\n\n        <!-- Cool Checkboxes -->\n        <smc-cool-checkboxes\n          class=\"smc-animated smc-fadeInRight smc-animDelay10\"\n        >\n          <smc-input-group data-edits=\"cool-checkbox\" data-eq=\"1\">\n            <label>\n              <input\n                type=\"checkbox\"\n                name=\"smc-agree1\"\n                value=\"yes\"\n                data-required=\"false\"\n              />\n              <smc-ccb-tick></smc-ccb-tick>\n              <smc-ccb-text\n                >I agree to the\n                <smc-show-terms data-id=\"terms1\">\n                  terms\n                </smc-show-terms></smc-ccb-text\n              >\n            </label>\n          </smc-input-group>\n          <smc-input-group data-edits=\"cool-checkbox\" data-eq=\"2\">\n            <label>\n              <input\n                type=\"checkbox\"\n                name=\"smc-agree2\"\n                value=\"yes\"\n                data-required=\"false\"\n              />\n              <smc-ccb-tick></smc-ccb-tick>\n              <smc-ccb-text\n                >I also agree to the\n                <smc-show-terms data-id=\"terms2\"\n                  >secondary terms</smc-show-terms\n                >\n                as well</smc-ccb-text\n              >\n            </label>\n          </smc-input-group>\n        </smc-cool-checkboxes>\n        <!-- End Cool Checkboxes -->\n        <input\n          class=\"smc-button smc-animated smc-fadeInRight smc-animDelay10\"\n          value=\"SUBMIT FORM\"\n          type=\"submit\"\n        />\n      </smc-option>\n\n      <!-- Data Consent Example - data-hidden-id=\"\" - Important to copy the new hidden inputs with copied values -->\n      <smc-option class=\"smc-dataConsent\">\n        <smc-input-group>\n          <input\n            class=\"smc-input smc-animated smc-fadeInLeft smc-animDelay8\"\n            data-required=\"true\"\n            data-verify=\"email\"\n            name=\"email\"\n            data-hidden-id=\"smc-consented-email\"\n            placeholder=\"ENTER YOUR EMAIL\"\n            type=\"text\"\n          />\n        </smc-input-group>\n        <!-- Cool Checkboxes -->\n        <smc-cool-checkboxes\n          class=\"smc-animated smc-fadeInRight smc-animDelay10\"\n        >\n          <smc-input-group data-edits=\"cool-checkbox\" data-eq=\"3\">\n            <label>\n              <input\n                type=\"checkbox\"\n                name=\"smc-agree1\"\n                value=\"yes\"\n                data-required=\"true\"\n              />\n              <smc-ccb-tick></smc-ccb-tick>\n              <smc-ccb-text\n                >I agree to the\n                <smc-show-terms data-id=\"terms1\">\n                  terms\n                </smc-show-terms></smc-ccb-text\n              >\n            </label>\n          </smc-input-group>\n          <smc-input-group data-edits=\"cool-checkbox\" data-eq=\"4\">\n            <label>\n              <input\n                type=\"checkbox\"\n                name=\"smc-agree2\"\n                value=\"yes\"\n                data-required=\"true\"\n              />\n              <smc-ccb-tick></smc-ccb-tick>\n              <smc-ccb-text\n                >I also agree to the\n                <smc-show-terms data-id=\"terms2\"\n                  >secondary terms</smc-show-terms\n                >\n                as well</smc-ccb-text\n              >\n            </label>\n          </smc-input-group>\n        </smc-cool-checkboxes>\n        <!-- End Cool Checkboxes -->\n        <input\n          class=\"smc-button smc-animated smc-fadeInRight smc-animDelay10\"\n          value=\"Save My Basket\"\n          type=\"submit\"\n        />\n      </smc-option>\n\n      <!-- Closers (Both Need) -->\n      <smc-long-close\n        class=\"smc-animated smc-fadeInUp smc-animDelay14\"\n        data-engage-class=\"smc-engaged\"\n      >\n        <a\n          data-close-type=\"long_close\"\n          class=\"smc-link smc-closer\"\n          href=\"#rdl\"\n          data-engage-text=\"{text11}\"\n          data-edits=\"text7,text11\"\n          data-changes=\"smc-long-close a.smc-link|font-size,color,margin-top,margin-bottom\"\n          >{text7}</a\n        >\n        <!-- Note - Redirect Link gets automatically rewritten, once clicked on the data-engage text and classes are applied -->\n      </smc-long-close>\n\n      <smc-close class=\"smc-animated smc-fadeInRight smc-animDelay4 smc-closer\">\n        <a data-close-type=\"x_close\" class=\"smc-link\" href=\"#rdl\">✕</a\n        ><!-- Note - Redirect Link gets automatically rewritten -->\n      </smc-close>\n\n      <!-- Success Message -->\n      <smc-success-message class=\"smc-animated smc-fadeIn\">\n        <smc-success-message-inner\n          class=\"smc-animated smc-bounceInDown smc-animDelay1\"\n        >\n          Perfect thank you!\n          <smc-success-close>X</smc-success-close>\n        </smc-success-message-inner>\n      </smc-success-message>\n\n      <!-- CSS Loader -->\n      <smc-loader-bg data-theme=\"white\"\n        ><!-- white, black-->\n        <smc-loader-single></smc-loader-single\n        ><!-- single, double, pulse -->\n      </smc-loader-bg>\n\n      <!-- Copy to Clipboard Success Message -->\n      <smc-cp-msg>\"{vc}\" has been copied to the clipboard</smc-cp-msg>\n    </smc-overlay-inner>\n    <smc-shake-msg>\n      <i class=\"fa fa-mobile\" aria-hidden=\"true\"></i><br />\n      Shake To Reaveal Voucher\n    </smc-shake-msg>\n  </smc-overlay-outer>\n\n  <!-- Safe close - Used when Autoscaling is turned on -->\n  <smc-close-safe class=\"smc-closer\">\n    <a data-close-type=\"x_close\" class=\"smc-link\" href=\"#rdl\">[close]</a\n    ><!-- Note - Redirect Link gets automatically rewritten -->\n  </smc-close-safe>\n</smc-bg>\n\n<!-- SmarterBar -->\n<smc-bar class=\"smc-animated smc-fadeInDown\">\n  <smc-bar-close>X</smc-bar-close>\n  <smc-bar-text>{smarterbar}</smc-bar-text>\n  <smc-handle>\n    <span class=\"smc-bar1\"></span>\n    <span class=\"smc-bar2\"></span>\n    <span class=\"smc-bar3\"></span>\n  </smc-handle>\n</smc-bar>\n\n<!-- Final Mesage Box -->\n<smc-final-message class=\"smc-animated smc-fadeInDown\"\n  >Thanks... your code is: {vc}<smc-final-message-close\n    >X</smc-final-message-close\n  ></smc-final-message\n>","opt":"smc-clickRedirect"},"PR0010":{"css":"@import url(https://fonts.smct.co/PANGAIA/PANGAIA.css);\n\nsmc-overlay-inner {\n\t--smc-mainBkg: #f8f8f8;\n\t--smc-cardBkg: #ffffff;\n\t--smc-textColour: #000000;\n\t--smc-textColour2: #19124f;\n\t--smc-borderColour: #e7e7e7;\n\t--smc-accent: #002fa7;\n\t--smc-font2: \"PANGAIA-Grade_04\", sans-serif;\n\t--smc-btnBkg: #000000;\n\t--smc-btnText: #ffffff;\n\t--smc-btnBorderRadius: 40px;\n\t--smc-frameBorderRadius: 4px;\n\t--smc-cardBorderRadius: 5px;\n\t--smc-btnFontSize: 10px;\n\t--smc-btnPadding: 8px 9px 9px 9px;\n}\n\nsmc-bg * {\n\tfont-family: \"PANGAIA-Grade_02\", sans-serif;\n}\n\nsmc-bg {\n\twidth: 100%;\n\theight: 100%;\n\tposition: fixed;\n\tbottom: 0;\n\tright: 0;\n\tleft: auto;\n\ttop: auto;\n\toverflow: hidden;\n\tbackground-color: rgba(0, 0, 0, 0);\n}\n\nsmc-overlay-outer {\n\tposition: absolute;\n\tbottom: 10px;\n\tleft: 10px;\n\tright: auto;\n}\n\nsmc-overlay-inner {\n\tbackground-color: var(--smc-mainBkg);\n\twidth: 660px;\n\tmin-height: 240px;\n\tmax-height: 240px;\n\tpadding-bottom: 0;\n\t/*overflow: hidden;*/\n\tborder-radius: var(--smc-frameBorderRadius);\n\tborder: 1px solid #d9d9d973;\n\tbox-shadow: 0 0 20px #00000014;\n\n\tposition: relative;\n\tbottom: 0;\n\tright: 0;\n\tmargin: auto;\n\tpointer-events: all;\n}\n\n/* Align the content Left */\nsmc-img-outer,\nsmc-text-outer,\nsmc-option,\nsmc-long-close {\n\tmin-width: 460px !important;\n\tmax-width: 460px !important;\n\tmargin: auto;\n}\n\n.smc-text1,\n.smc-text2,\n.smc-text3 {\n\tfont-size: 12px;\n\tfont-weight: 400;\n\tmargin: 8px auto;\n\tcolor: var(--smc-textColour);\n\ttext-align: center;\n\tline-height: 1.2;\n}\n\n.smc-text1 {\n\tfont-size: 24px;\n\tfont-weight: bold;\n\tmargin: 5px auto auto auto;\n\tfont-family: var(--smc-font2);\n}\n\n.smc-text2 {\n\tline-height: 1.2;\n\tfont-family: \"PANGAIA-Grade_03\", sans-serif;\n}\n\nsmc-option {\n\tdisplay: none;\n}\n\n.smc-button {\n\tmax-width: 100px;\n\tmargin: 15px auto auto 0;\n\tbackground-color: var(--smc-btnBkg);\n\tcolor: var(--smc-btnText);\n\tpadding: 9px 9px 10px 9px;\n\tfont-size: 11px;\n\tfont-weight: bold;\n\tborder-radius: var(--smc-btnBorderRadius);\n}\n\nsmc-close {\n\tfont-size: 12px;\n}\n\nsmc-close a.smc-link {\n\tcolor: #00000050;\n}\n\nsmc-cart {\n\tposition: absolute;\n\tbottom: 20px;\n\tleft: 20px;\n\tbackground-color: var(--smc-cardBkg);\n\twidth: 620px;\n\theight: 135px;\n\tpadding: 10px;\n\tdisplay: flex;\n\tjustify-content: center;\n\toverflow: hidden;\n\tborder-radius: var(--smc-cardBorderRadius);\n\tgap: 10px;\n\talign-items: flex-start;\n\tborder: 1px solid var(--smc-borderColour);\n}\n\nsmc-product {\n\talign-self: center;\n\tflex: 1;\n\theight: 100%;\n\tdisplay: flex !important;\n\tflex-direction: row;\n\twidth: 50%;\n}\n\nsmc-product-img,\nsmc-product-name,\nsmc-product-rating,\nsmc-product-price,\nsmc-product-desc {\n\tdisplay: block;\n\tmargin: 5px auto;\n\tfont-weight: 300;\n\tfont-size: 14px;\n\tcolor: var(--smc-textColour2);\n\twidth: 100%;\n\ttext-align: left;\n}\n\nsmc-product-img {\n\tmax-width: 100px;\n\tdisplay: flex;\n\tmargin: 0 auto 0 auto;\n\tjustify-content: center;\n\talign-items: center;\n\tpadding: 0;\n}\n\nsmc-product-img img {\n\tmax-width: 100px;\n\tmargin: auto;\n\theight: 100%;\n}\n\nsmc-details {\n\tdisplay: flex;\n\talign-items: center;\n\tjustify-content: center;\n\twidth: 100%;\n\tflex-direction: column;\n}\n\nsmc-prices {\n\tdisplay: flex;\n\tpadding: 0 10px;\n\tcolumn-gap: 20px;\n\tmargin-top: 5px;\n\twidth: 100%;\n}\n\nsmc-product-name {\n\tfont-size: 13px;\n\ttext-overflow: ellipsis;\n\tcolor: var(--smc-textColour);\n\toverflow: hidden;\n\tpadding: 0 10px;\n\tdisplay: -webkit-box;\n\tmargin: -2px auto 5px 0;\n\t-webkit-line-clamp: 1;\n\t-webkit-box-orient: vertical;\n\tfont-weight: 600;\n\tline-height: 1.2;\n\tfont-family: var(--smc-font2);\n}\n\nsmc-product-price {\n\tfont-weight: 600;\n\tfont-size: 12px;\n\tcolor: var(--smc-textColour);\n\tmargin: 0;\n}\n\nsmc-product-oldprice {\n\tfont-weight: 400;\n\tfont-size: 12px;\n\tcolor: var(--smc-textColour);\n\tmargin: 0;\n\ttext-decoration: line-through;\n}\n\nsmc-product-link {\n\tmargin: 14px auto 0 10px;\n\twidth: 90px;\n\tpadding: var(--smc-btnPadding);\n\tfont-size: var(--smc-btnFontSize);\n\ttext-align: center;\n\tborder-radius: 9px;\n\tbackground-color: var(--smc-btnBkg);\n\tcolor: var(--smc-btnText);\n\tdisplay: block;\n\tcursor: pointer;\n}\nsmc-badge {\n\tposition: absolute;\n\tbottom: 20px;\n\tleft: 20px;\n\twidth: 280px;\n\theight: 50px;\n\tfont-weight: bold;\n\tfont-size: 16px;\n\tbackground-color: #000;\n\tborder-radius: 999px;\n\tcolor: #fff;\n\tdisplay: flex;\n\talign-items: center;\n\tjustify-content: center;\n\ttext-align: center;\n\tcursor: pointer;\n\tbackground: var(--smc-accent);\n\tbackground-size: 200% 200%;\n\tflex-direction: column;\n}\n/* @media only screen and (max-width: 1850px) {\n  smc-badge {\n    left: 790px;\n  }\n} */\n","html":"<!-- Overlay V4 Template -->\n<smc-bg class=\"smc-animated smc-fadeIn\">\n    <smc-badge>Still Thinking It Over?<br><span>See More to Help You Decide</span></smc-badge>\n\t<smc-overlay-outer class=\"smc-animated smc-fadeInUp smc-animDelay2\"> <!--  data-animout=\"smc-bounceOutLeft\" --> \n        <smc-overlay-inner class=\"smc_clearfix\" data-bgtheme=\"dark\" data-changes=\"smc-overlay-inner|width,background-image,background-color\" data-edits=\"content6\"><!-- If the background is dark use this option -->\n            \n            <smc-cart>\n                <smc-product>\n                    <smc-product-img><img src=\"https://pangaia.com/cdn/shop/products/Organic-Cotton-Hoodie-Stone-1.png?v=1662475629&amp;width=550\"></smc-product-img>\n                    <smc-details>\n                    <smc-product-name>365 Midweight Hoodie</smc-product-name>\n                        <smc-prices>\n                            <smc-product-oldprice>£160</smc-product-oldprice>\n                            <smc-product-price>£130</smc-product-price>\n                        </smc-prices>\n                    <smc-product-link>View item</smc-product-link>\n                    </smc-details>\n                </smc-product>\n                <smc-product>\n                    <smc-product-img><img src=\"https://pangaia.com/cdn/shop/products/Organic-Cotton-Hoodie-Stone-1.png?v=1662475629&amp;width=550\"></smc-product-img>\n                    <smc-details>\n                    <smc-product-name>365 Midweight Hoodie</smc-product-name>\n                        <smc-prices>\n                            <smc-product-oldprice>£160</smc-product-oldprice>\n                            <smc-product-price>£130</smc-product-price>\n                        </smc-prices>\n                    <smc-product-link>View item</smc-product-link>\n                    </smc-details>\n                </smc-product>\n            </smc-cart>\n            \n            <!-- Images - You can add as many as you like -->\n            <smc-img-outer>\n                <smc-img class=\"smc-img1\" data-changes=\".smc-img1|margin-top,margin-bottom,image-upload\" data-edits=\"content1\"><img src=\"{content1}\" alt=\"\"></smc-img>\n                <smc-img class=\"smc-img2\" data-changes=\".smc-img2|margin-top,margin-bottom,image-upload\" data-edits=\"content2\"><img src=\"{content2}\" alt=\"\"></smc-img>\n                <smc-img class=\"smc-img3\" data-changes=\".smc-img3|margin-top,margin-bottom,image-upload\" data-edits=\"content3\"><img src=\"{content3}\" alt=\"\"></smc-img>\n                <smc-img class=\"smc-img4\" data-changes=\".smc-img4|margin-top,margin-bottom,image-upload\" data-edits=\"content4\"><img src=\"{content4}\" alt=\"\"></smc-img>\n            </smc-img-outer>\n            \n            <!-- Text Boxes - You can add as many as you like -->\n            <smc-text-outer>\n                <smc-text class=\"smc-text1\" data-edits=\"text1\" data-changes=\".smc-text1|font-size,color,margin-top,margin-bottom\">{text1}</smc-text>\n                <smc-text class=\"smc-text2\" data-edits=\"text2\" data-changes=\".smc-text2|font-size,color,margin-top,margin-bottom\">{text2}</smc-text>\n                <smc-text class=\"smc-text3\" data-edits=\"text3\" data-changes=\".smc-text3|font-size,color,margin-top,margin-bottom\">{text3}</smc-text>\n                <smc-text class=\"smc-text4\" data-edits=\"text4\" data-changes=\".smc-text4|font-size,color,margin-top,margin-bottom\">{text4}</smc-text>\n            </smc-text-outer>\n            \n            <!-- Email Voucher Option -->\n            <smc-option class=\"smc-email\">\n                <smc-input-group><input class=\"smc-input smc-animated smc-fadeInLeft smc-animDelay8\" name=\"email\" autocomplete=\"smc-autocomplete\" data-required=\"true\" data-verify=\"email\" placeholder=\"ENTER YOUR EMAIL HERE\" type=\"text\"></smc-input-group>\n                <smc-input-group><input class=\"smc-button smc-animated smc-fadeInRight smc-animDelay10\" value=\"Email Voucher\" type=\"submit\"></smc-input-group>\n            </smc-option>\n            \n            <!-- Click To Reveal Option -->\n            <smc-option class=\"smc-clickToReveal\">\n                <smc-reveal class=\"smc-animated smc-bounceInUp smc-animDelay12\">\n                    <smc-cover data-edits=\"text8\" data-changes=\".smc-clickToReveal smc-cover|font-size,background-color,color\">{text8}</smc-cover>\n                    <smc-code>{vc}</smc-code>\n                    <smc-cp data-clipboard-text=\"{vc-cp}\"></smc-cp>\n                </smc-reveal>\n            </smc-option>\n            \n            <!-- Email To Reveal Option -->\n            <smc-option class=\"smc-emailToReveal\">\n                <smc-input-group><input class=\"smc-input smc-animated smc-fadeInLeft smc-animDelay8\" name=\"email\" autocomplete=\"smc-autocomplete\" data-required=\"true\" data-verify=\"email\" placeholder=\"{text13}\" type=\"text\"></smc-input-group>\n                <smc-reveal class=\"smc-animated smc-bounceInUp smc-animDelay12\">\n                    <smc-cover data-edits=\"text9\" data-changes=\".smc-emailToReveal smc-cover|font-size,background-color,color\">{text9}</smc-cover>\n                    <smc-code>{vc}</smc-code>\n                    <smc-cp data-clipboard-text=\"{vc-cp}\"></smc-cp>\n                </smc-reveal>    \n            </smc-option>\n\n            <!-- Uniqodo Email To Reveal Option -->\n            <smc-option class=\"smc-uniqodoEmailToReveal\">\n                <smc-input-group><input class=\"smc-input smc-animated smc-fadeInLeft smc-animDelay8\" name=\"email\" autocomplete=\"smc-autocomplete\" data-required=\"true\" data-verify=\"email\" placeholder=\"{text13}\" type=\"text\"></smc-input-group>\n                <smc-reveal class=\"smc-animated smc-bounceInUp smc-animDelay12\">\n                    <smc-cover data-edits=\"text9\" data-changes=\".smc-emailToReveal smc-cover|font-size,background-color,color\">{text9}</smc-cover>\n                    <smc-code>{vc}</smc-code>\n                    <smc-cp data-clipboard-text=\"{vc-cp}\"></smc-cp>\n                </smc-reveal>    \n            </smc-option>\n\n            <!-- Uniqodo Click To Reveal Option -->\n            <smc-option class=\"smc-uniqodoCodeReveal\">\n                <smc-reveal class=\"smc-animated smc-bounceInUp smc-animDelay12\">\n                    <smc-cover data-edits=\"text8\" data-changes=\".smc-uniqodoCodeReveal smc-cover|font-size,background-color,color\">{text8}</smc-cover>\n                    <smc-code>{vc}</smc-code>\n                    <smc-cp data-clipboard-text=\"{vc-cp}\"></smc-cp>\n                </smc-reveal>\n            </smc-option>\n            \n            <!-- Click To Redirect Option -->\n            <smc-option class=\"smc-clickRedirect\">\n                <smc-input-group>\n                \t<span class=\"smc-button\" data-edits=\"text10\" data-changes=\".smc-button|font-size,background-color,color\">{text10}</span>\n                </smc-input-group>\n            </smc-option>\n\n            <!-- Email to GiftCloud Option -->\n            <smc-option class=\"smc-emailToGiftCloud\">\n                <smc-input-group><input class=\"smc-input smc-animated smc-fadeInLeft smc-animDelay8\" name=\"email\" autocomplete=\"smc-autocomplete\" data-required=\"true\" data-verify=\"email\" placeholder=\"{text13}\" type=\"text\"></smc-input-group>\n                <smc-reveal class=\"smc-animated smc-bounceInUp smc-animDelay12\">\n                    <smc-cover data-edits=\"text12\" data-changes=\".smc-emailToReveal smc-cover|font-size,background-color,color\">{text12}</smc-cover>\n                </smc-reveal>    \n            </smc-option>\n            \n\t\t\t<!-- Request Notifications -->\n\t\t\t<smc-option class=\"smc-requestNotifications\">\n\t\t\t   <smc-input-group>\n\t\t\t\t   <span class=\"smc-button smc-animated smc-fadeInRight smc-animDelay10\" data-close-timeout=\"2000\">Enable Notifications</span>\n\t\t\t   </smc-input-group>\n\t\t\t   <smc-agree-yes class=\"smc-animated smc-fadeIn\">Thanks for enabling</smc-agree-yes>\n\t\t\t   <smc-agree-no class=\"smc-animated smc-fadeIn\">Ok no problem</smc-agree-no>\n\t\t\t</smc-option>\n\n            <!-- Dynamic Form Example -->\n            <smc-option class=\"smc-dynamicForm\">\n                <smc-input-group><input class=\"smc-input smc-animated smc-fadeInLeft smc-animDelay6\" data-required=\"true\" autocomplete=\"smc-autocomplete\" name=\"fullname\" placeholder=\"ENTER YOUR NAME\" type=\"text\"></smc-input-group>\n                <smc-input-group><input class=\"smc-input smc-animated smc-fadeInLeft smc-animDelay7\" data-required=\"true\" autocomplete=\"smc-autocomplete\" name=\"address\" placeholder=\"YOUR ADDRESS\" type=\"text\"></smc-input-group>\n                <smc-input-group><input class=\"smc-input smc-animated smc-fadeInLeft smc-animDelay8\" data-required=\"true\" autocomplete=\"smc-autocomplete\" data-verify=\"email\" name=\"email\" placeholder=\"YOUR EMAIL\" type=\"text\"></smc-input-group>\n                <smc-input-group>\n                    <div class=\"smc-animated smc-fadeInLeft smc-animDelay9\">\n                        <label><input type=\"radio\" name=\"sex\" data-required=\"true\" value=\"male\">Male</label>\n                        <label><input type=\"radio\" name=\"sex\" data-required=\"true\" value=\"female\">Female</label>\n                        <label><input type=\"radio\" name=\"sex\" data-required=\"true\" value=\"other\">Other</label>\n                    </div>\n                </smc-input-group>\n\n                <!-- Cool Checkboxes -->\n                <smc-cool-checkboxes class=\"smc-animated smc-fadeInRight smc-animDelay10\">\n                    <smc-input-group data-edits=\"cool-checkbox\" data-eq=\"1\">\n                        <label>\n                            <input type=\"checkbox\" name=\"smc-agree1\" value=\"yes\" data-required=\"false\">\n                            <smc-ccb-tick></smc-ccb-tick>\n                            <smc-ccb-text>I agree to the <smc-show-terms data-id=\"terms1\"> terms </smc-show-terms></smc-ccb-text>\n                        </label>\n                    </smc-input-group>\n                    <smc-input-group data-edits=\"cool-checkbox\" data-eq=\"2\">\n                        <label>\n                    \t    <input type=\"checkbox\" name=\"smc-agree2\" value=\"yes\" data-required=\"false\">\n                    \t    <smc-ccb-tick></smc-ccb-tick>\n                    \t    <smc-ccb-text>I also agree to the <smc-show-terms data-id=\"terms2\">secondary terms</smc-show-terms> as well</smc-ccb-text>\n                        </label>\n                    </smc-input-group>\n                </smc-cool-checkboxes>\n                <!-- End Cool Checkboxes -->\n                <input class=\"smc-button smc-animated smc-fadeInRight smc-animDelay10\" value=\"SUBMIT FORM\" type=\"submit\">\n            </smc-option>\n\n            <!-- Data Consent Example - data-hidden-id=\"\" - Important to copy the new hidden inputs with copied values -->\n            <smc-option class=\"smc-dataConsent\">\n                <smc-input-group>\n                    <input class=\"smc-input smc-animated smc-fadeInLeft smc-animDelay8\" data-required=\"true\" data-verify=\"email\" name=\"email\" data-hidden-id=\"smc-consented-email\" placeholder=\"ENTER YOUR EMAIL\" type=\"text\">\n                </smc-input-group>\n                <!-- Cool Checkboxes -->\n                <smc-cool-checkboxes class=\"smc-animated smc-fadeInRight smc-animDelay10\">\n                    <smc-input-group data-edits=\"cool-checkbox\" data-eq=\"3\">\n                        <label>\n                            <input type=\"checkbox\" name=\"smc-agree1\" value=\"yes\" data-required=\"true\">\n                            <smc-ccb-tick></smc-ccb-tick>\n                            <smc-ccb-text>I agree to the <smc-show-terms data-id=\"terms1\"> terms </smc-show-terms></smc-ccb-text>\n                        </label>\n                    </smc-input-group>\n                    <smc-input-group data-edits=\"cool-checkbox\" data-eq=\"4\">\n                        <label>\n                            <input type=\"checkbox\" name=\"smc-agree2\" value=\"yes\" data-required=\"true\">\n                            <smc-ccb-tick></smc-ccb-tick>\n                            <smc-ccb-text>I also agree to the <smc-show-terms data-id=\"terms2\">secondary terms</smc-show-terms> as well</smc-ccb-text>\n                        </label>\n                    </smc-input-group>\n                </smc-cool-checkboxes>\n                <!-- End Cool Checkboxes -->\n                <input class=\"smc-button smc-animated smc-fadeInRight smc-animDelay10\" value=\"Save My Basket\" type=\"submit\">\n            </smc-option>\n\n            <!-- Closers (Both Need) -->\n            <smc-long-close class=\"smc-animated smc-fadeInUp smc-animDelay14\" data-engage-class=\"smc-engaged\">\n                <a data-close-type=\"long_close\" class=\"smc-link smc-closer\" href=\"#rdl\" data-engage-text=\"{text11}\" data-edits=\"text7,text11\" data-changes=\"smc-long-close a.smc-link|font-size,color,margin-top,margin-bottom\">{text7}</a>\n                <!-- Note - Redirect Link gets automatically rewritten, once clicked on the data-engage text and classes are applied -->\n            </smc-long-close>\n\n            <smc-close class=\"smc-animated smc-fadeInRight smc-animDelay4 smc-closer\">\n                <a data-close-type=\"x_close\" class=\"smc-link\" href=\"#rdl\">✕</a><!-- Note - Redirect Link gets automatically rewritten -->\n            </smc-close>\n            \n\n            <!-- Success Message -->\n            <smc-success-message class=\"smc-animated smc-fadeIn\">\n                <smc-success-message-inner class=\"smc-animated smc-bounceInDown smc-animDelay1\">\n                    Perfect thank you!\n                    <smc-success-close>X</smc-success-close>\n                </smc-success-message-inner>    \n            </smc-success-message>\n            \n            <!-- CSS Loader -->\n            <smc-loader-bg data-theme=\"white\"><!-- white, black-->\n                <smc-loader-single></smc-loader-single><!-- single, double, pulse -->\n            </smc-loader-bg>\n \n            <!-- Copy to Clipboard Success Message -->\n            <smc-cp-msg>\"{vc}\" has been copied to the clipboard</smc-cp-msg>\n\n        </smc-overlay-inner>\n        <smc-shake-msg>\n            <i class=\"fa fa-mobile\" aria-hidden=\"true\"></i><br>\n            Shake To Reaveal Voucher\n        </smc-shake-msg>\n    </smc-overlay-outer>\n    \n    <!-- Safe close - Used when Autoscaling is turned on -->\n    <smc-close-safe class=\"smc-closer\">\n    \t<a data-close-type=\"x_close\" class=\"smc-link\" href=\"#rdl\">[close]</a><!-- Note - Redirect Link gets automatically rewritten -->\n    </smc-close-safe>\n</smc-bg>\n\n<!-- SmarterBar -->\n<smc-bar class=\"smc-animated smc-fadeInDown\">\n    <smc-bar-close>X</smc-bar-close>\n    <smc-bar-text>{smarterbar}</smc-bar-text>\n    <smc-handle>\n        <span class=\"smc-bar1\"></span>\n        <span class=\"smc-bar2\"></span>\n        <span class=\"smc-bar3\"></span>\n    </smc-handle>\n</smc-bar>\n\n<!-- Final Mesage Box -->\n<smc-final-message class=\"smc-animated smc-fadeInDown\">Thanks... your code is: {vc}<smc-final-message-close>X</smc-final-message-close></smc-final-message>","opt":""},"PR0011":{"css":"@import url('https://fonts.smct.co/Avenir/font.css');\nsmc-bg *{font-family: 'Avenir Next W01', sans-serif;}\n\nsmc-overlay-inner {\n    --smc-mainBkg: #ffd814;\n    --smc-textColour: #222;\n    --smc-btnBkg: #000;\n    --smc-frameBorderRadius: 2px;\n    --smc-btnBorderRadius: var(--smc-frameBorderRadius);\n    --smc-btnFontSize: 14px;\n    --smc-btnPadding: 10px;\n}\n\nsmc-overlay-inner {\n    background-color: #fff;\n    background-size: cover;\n    width: 540px;\n    min-height: auto;\n    border-radius: 2px;\n    padding:30px;\n    overflow: hidden;\n}\n\n/* Align the content Left */\nsmc-img-outer,\nsmc-text-outer,\nsmc-long-close {\n    width: 90%;\n}\n\n.smc-text1,\n.smc-text2 {\n    font-size: 16px;\n    font-weight: 400;\n    margin: 20px auto;\n    text-align: center;\n    color:#000;\n    line-height: 130%;\n}\n\n.smc-text1 {\n    margin: 0px auto 10px auto;\n    font-size: 20px;\n    text-transform: uppercase;\n}\n\nsmc-option {\n    display: none;\n}\n\nsmc-close {\n    font-size: 14px;\n    top: 10px;\n    right: 10px;\n}\n\nsmc-close a.smc-link {\n    color: #000;\n}\n\n\n/* ******************CART******************* */\n/* ******************CART******************* */\n/* ******************CART******************* */\n\nsmc-cart {\n    margin: 10px auto;\n    background: #fff;\n    width: 100%;\n    border-radius: 3px;\n    gap: 10px;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n}\n\nsmc-product {\n    align-self: center;\n    width: 50%;\n    margin: auto;\n    display: flex;\n    flex-direction: column;\n    /* border: 1px solid #e5e5e5; */\n}\n\nsmc-left,\nsmc-right {\n    display: flex;\n    flex-direction: column;\n    padding: 10px;\n    justify-content: center;\n}\n\nsmc-left {\n    width: 100%;\n}\n\nsmc-right {\n    width: 100%;\n    align-self: center;\n    gap: 3px;\n}\n\nsmc-product-name,\nsmc-product-desc {\n    display: flex;\n    margin: 0;\n    text-align: left;\n    font-weight: 300;\n    font-size: 14px;\n    color: var(--smc-textColour);\n}\n\nsmc-product-img {\n    max-width: 160px;\n    max-height: 160px;\n    display: flex;\n    align-items: center;\n    overflow: hidden;\n    margin: auto;\n}\n\nsmc-product-img img {\n    width: 100%;\n    height: auto;\n}\nsmc-product-brand,\nsmc-product-name,\nsmc-product-desc {\n    text-overflow: ellipsis;\n    overflow: hidden;\n    display: -webkit-box;\n    text-align: left;\n    -webkit-line-clamp: 2;\n    -webkit-box-orient: vertical;\n    line-height: 1.2;\n    font-size: 14px;\n    width: 100%;\n    color: var(--smc-textColour);\n}\nsmc-product-brand {\n    font-weight: 600;\n    text-transform: uppercase;\n}\nsmc-product-name {\n\ttext-overflow: ellipsis;\n\toverflow: hidden;\n\tdisplay: -webkit-box;\n\t-webkit-line-clamp: 1;\n\t-webkit-box-orient: vertical;\n\tline-height: 1.2;\n}\nsmc-product-desc {\n    color: #bbb;\n}\n\nsmc-prices {\n    display: flex;\n    flex-direction: row;\n    justify-content: flex-start;\n    width: 100%;\n    align-content: center;\n    flex-wrap: wrap;\n    align-items: center;\n}\n\nsmc-product-price {\n    color: var(--smc-textColour);\n    font-size: 14px;\n    font-weight: 600;\n}\n\nsmc-old-price {\n    text-decoration: line-through;\n    line-height: 1.3;\n    padding: 0 10px 0 0;\n    color: var(--smc-textColour);\n    opacity: 0.3;\n    font-size: 14px;\n}\n\nsmc-old-price:empty {\n    padding: 0;\n}\nsmc-product-link{\n    font-weight:400;\n    max-width:240px;\n    border-radius:var(--smc-btnBorderRadius);\n    cursor:pointer;\n    width:100%;\n    display:flex;\n    justify-content:center;\n    margin: 10px auto 0 0;\n    font-size: var(--smc-btnFontSize);\n    padding: var(--smc-btnPadding);\n    background-color: var(--smc-btnBkg);\n    color: #fff;\n    text-transform: uppercase;\n}\nsmc-product-link:hover{\n    background-color:#333;\n    color:#fff;\n}\n","html":"<!-- Overlay V4 Template -->\n<smc-bg class=\"smc-animated smc-fadeIn\">\n\t<smc-overlay-outer> <!--  data-animout=\"smc-bounceOutLeft\" --> \n        <smc-overlay-inner class=\"smc_clearfix\" data-bgtheme=\"dark\" data-changes=\"smc-overlay-inner|width,background-image,background-color\" data-edits=\"content6\"><!-- If the background is dark use this option -->\n            \n   \n\n\n            <smc-img class=\"smc-img1 smc-animated smc-bounceInDown smc-animDelay6\" data-changes=\".smc-img1|margin-top,margin-bottom,image-upload\" data-edits=\"content1\"><img src=\"{content1}\" alt=\"\"></smc-img>\n            <!-- Images - You can add as many as you like -->\n            <smc-img-outer>\n                \n                <smc-img class=\"smc-img2 smc-animated smc-bounceInRight smc-animDelay8\" data-changes=\".smc-img2|margin-top,margin-bottom,image-upload\" data-edits=\"content2\"><img src=\"{content2}\" alt=\"\"></smc-img>\n                <smc-img class=\"smc-img3 smc-animated smc-bounceInRight smc-animDelay10\" data-changes=\".smc-img3|margin-top,margin-bottom,image-upload\" data-edits=\"content3\"><img src=\"{content3}\" alt=\"\"></smc-img>\n            </smc-img-outer>\n            \n            <!-- Text Boxes - You can add as many as you like -->\n            <smc-text-outer>\n                <smc-text class=\"smc-text1\" data-edits=\"text1\" data-changes=\".smc-text1|font-size,color,margin-top,margin-bottom\">{text1}</smc-text>\n                <smc-text class=\"smc-text2 smc-animated smc-bounceInRight smc-animDelay6\" data-edits=\"text2\" data-changes=\".smc-text2|font-size,color,margin-top,margin-bottom\">{text2}</smc-text>\n                <smc-text class=\"smc-text3 smc-animated smc-bounceInLeft smc-animDelay8\" data-edits=\"text3\" data-changes=\".smc-text3|font-size,color,margin-top,margin-bottom\">{text3}</smc-text>\n                <smc-text class=\"smc-text4 smc-animated smc-bounceInRight smc-animDelay10\" data-edits=\"text4\" data-changes=\".smc-text4|font-size,color,margin-top,margin-bottom\">{text4}</smc-text>\n            </smc-text-outer>\n\n\n                    <smc-cart>\n                        <smc-product>\n                            <smc-left>\n                                <smc-product-img><img src=\"https://statics-cdn-v2.fashionette.net/transform/bf5ebe73-0b0f-4c89-87a7-446b715f7b51/A0684138-PDP-1?io=transform:extend,width:320,height:320,background:white&amp;quality=100&amp;format=webp\"></smc-product-img>\n                            </smc-left>\n                            <smc-right>\n                                <smc-product-brand>Coccinelle</smc-product-brand>\n                                <smc-product-name>Coccinellerebekka Noir</smc-product-name>\n                                <smc-prices>\n                                    <smc-old-price></smc-old-price><smc-product-price>220 €</smc-product-price>\n                                </smc-prices>\n                                <smc-product-link>{text14}</smc-product-link>\n                            </smc-right>\n                        </smc-product>\n                        <smc-product>\n                            <smc-left>\n                                <smc-product-img><img src=\"https://statics-cdn-v2.fashionette.net/transform/fe7f2f79-8778-4184-8bc7-63388b68fd28/dcc4d0702ffce5f937a0bc499fe2fc7502c832ac?io=transform:extend,width:320,height:320,background:white&amp;quality=100&amp;format=webp\"></smc-product-img>\n                            </smc-left>\n                            <smc-right>\n                                <smc-product-brand>Rolex</smc-product-brand>\n                                <smc-product-name>Oyster Perpetual Blau</smc-product-name>\n                                <smc-prices>\n                                    <smc-old-price></smc-old-price><smc-product-price>7.500 €</smc-product-price>\n                                </smc-prices>\n                                <smc-product-link>{text14}</smc-product-link>\n                            </smc-right>\n                        </smc-product>\n                    </smc-cart>\n\n\n            \n            <!-- Email Voucher Option -->\n            <smc-option class=\"smc-email\">\n                <smc-input-group><input class=\"smc-input smc-animated smc-fadeInLeft smc-animDelay8\" name=\"email\" autocomplete=\"smc-autocomplete\" data-required=\"true\" data-verify=\"email\" placeholder=\"ENTER YOUR EMAIL HERE\" type=\"text\"></smc-input-group>\n                <smc-input-group><input class=\"smc-button smc-animated smc-fadeInRight smc-animDelay10\" value=\"Email Voucher\" type=\"submit\"></smc-input-group>\n            </smc-option>\n            \n              <!-- Click To Redirect Option -->\n            <smc-option class=\"smc-clickRedirect\">\n                <smc-input-group>\n                    <span class=\"smc-button smc-animated smc-fadeInRight smc-animDelay10\" data-edits=\"text10\" data-changes=\".smc-button|font-size,background-color,color\">{text10}</span>\n                </smc-input-group>\n            </smc-option>\n\n\n            <!-- Click To Reveal Option -->\n            <smc-option class=\"smc-clickToReveal\">\n                <smc-reveal class=\"smc-animated smc-bounceInUp smc-animDelay12\">\n                    <smc-cover data-edits=\"text8\" data-changes=\".smc-clickToReveal smc-cover|font-size,background-color,color\">{text8}</smc-cover>\n                    <smc-code>{vc}</smc-code>\n                    <smc-cp data-clipboard-text=\"{vc-cp}\"></smc-cp>\n                </smc-reveal>\n            </smc-option>\n            \n            <!-- Email To Reveal Option -->\n            <smc-option class=\"smc-emailToReveal\">\n                <smc-input-group><input class=\"smc-input smc-animated smc-fadeInLeft smc-animDelay8\" name=\"email\" autocomplete=\"smc-autocomplete\" data-required=\"true\" data-verify=\"email\" placeholder=\"{text13}\" type=\"text\"></smc-input-group>\n                <smc-reveal class=\"smc-animated smc-bounceInUp smc-animDelay12\">\n                    <smc-cover data-edits=\"text9\" data-changes=\".smc-emailToReveal smc-cover|font-size,background-color,color\">{text9}</smc-cover>\n                    <smc-code>{vc}</smc-code>\n                    <smc-cp data-clipboard-text=\"{vc-cp}\"></smc-cp>\n                </smc-reveal>    \n            </smc-option>\n            \n           \n\n            <!-- Email to GiftCloud Option -->\n            <smc-option class=\"smc-emailToGiftCloud\">\n                <smc-input-group><input class=\"smc-input smc-animated smc-fadeInLeft smc-animDelay8\" name=\"email\" autocomplete=\"smc-autocomplete\" data-required=\"true\" data-verify=\"email\" placeholder=\"{text13}\" type=\"text\"></smc-input-group>\n                <smc-reveal class=\"smc-animated smc-bounceInUp smc-animDelay12\">\n                    <smc-cover data-edits=\"text12\" data-changes=\".smc-emailToReveal smc-cover|font-size,background-color,color\">{text12}</smc-cover>\n                </smc-reveal>    \n            </smc-option>\n            \n\t\t\t<!-- Request Notifications -->\n\t\t\t<smc-option class=\"smc-requestNotifications\">\n\t\t\t   <smc-input-group>\n\t\t\t\t   <span class=\"smc-button smc-animated smc-fadeInRight smc-animDelay10\" data-close-timeout=\"2000\">Enable Notifications</span>\n\t\t\t   </smc-input-group>\n\t\t\t   <smc-agree-yes class=\"smc-animated smc-fadeIn\">Thanks for enabling</smc-agree-yes>\n\t\t\t   <smc-agree-no class=\"smc-animated smc-fadeIn\">Ok no problem</smc-agree-no>\n\t\t\t</smc-option>\n\n            <!-- Dynamic Form Example -->\n            <smc-option class=\"smc-dynamicForm\">\n                <smc-input-group><input class=\"smc-input smc-animated smc-fadeInLeft smc-animDelay6\" data-required=\"true\" autocomplete=\"smc-autocomplete\" name=\"fullname\" placeholder=\"ENTER YOUR NAME\" type=\"text\"></smc-input-group>\n                <smc-input-group><input class=\"smc-input smc-animated smc-fadeInLeft smc-animDelay7\" data-required=\"true\" autocomplete=\"smc-autocomplete\" name=\"address\" placeholder=\"YOUR ADDRESS\" type=\"text\"></smc-input-group>\n                <smc-input-group><input class=\"smc-input smc-animated smc-fadeInLeft smc-animDelay8\" data-required=\"true\" autocomplete=\"smc-autocomplete\" data-verify=\"email\" name=\"email\" placeholder=\"YOUR EMAIL\" type=\"text\"></smc-input-group>\n                <smc-input-group>\n                    <div class=\"smc-animated smc-fadeInLeft smc-animDelay9\">\n                        <label><input type=\"radio\" name=\"sex\" data-required=\"true\" value=\"male\">Male</label>\n                        <label><input type=\"radio\" name=\"sex\" data-required=\"true\" value=\"female\">Female</label>\n                        <label><input type=\"radio\" name=\"sex\" data-required=\"true\" value=\"other\">Other</label>\n                    </div>\n                </smc-input-group>\n\n                <!-- Cool Checkboxes -->\n                <smc-cool-checkboxes class=\"smc-animated smc-fadeInRight smc-animDelay10\">\n                    <smc-input-group data-edits=\"cool-checkbox\" data-eq=\"1\">\n                        <label>\n                            <input type=\"checkbox\" name=\"smc-agree1\" value=\"yes\" data-required=\"false\">\n                            <smc-ccb-tick></smc-ccb-tick>\n                            <smc-ccb-text>I agree to the <smc-show-terms data-id=\"terms1\"> terms </smc-show-terms></smc-ccb-text>\n                        </label>\n                    </smc-input-group>\n                    <smc-input-group data-edits=\"cool-checkbox\" data-eq=\"2\">\n                        <label>\n                    \t    <input type=\"checkbox\" name=\"smc-agree2\" value=\"yes\" data-required=\"false\">\n                    \t    <smc-ccb-tick></smc-ccb-tick>\n                    \t    <smc-ccb-text>I also agree to the <smc-show-terms data-id=\"terms2\">secondary terms</smc-show-terms> as well</smc-ccb-text>\n                        </label>\n                    </smc-input-group>\n                </smc-cool-checkboxes>\n                <!-- End Cool Checkboxes -->\n                <input class=\"smc-button smc-animated smc-fadeInRight smc-animDelay10\" value=\"SUBMIT FORM\" type=\"submit\">\n            </smc-option>\n\n            <!-- Data Consent Example - data-hidden-id=\"\" - Important to copy the new hidden inputs with copied values -->\n            <smc-option class=\"smc-dataConsent\">\n                <smc-input-group>\n                    <input class=\"smc-input smc-animated smc-fadeInLeft smc-animDelay8\" data-required=\"true\" data-verify=\"email\" name=\"email\" data-hidden-id=\"smc-consented-email\" placeholder=\"ENTER YOUR EMAIL\" type=\"text\">\n                </smc-input-group>\n                <!-- Cool Checkboxes -->\n                <smc-cool-checkboxes class=\"smc-animated smc-fadeInRight smc-animDelay10\">\n                    <smc-input-group data-edits=\"cool-checkbox\" data-eq=\"3\">\n                        <label>\n                            <input type=\"checkbox\" name=\"smc-agree1\" value=\"yes\" data-required=\"true\">\n                            <smc-ccb-tick></smc-ccb-tick>\n                            <smc-ccb-text>I agree to the <smc-show-terms data-id=\"terms1\"> terms </smc-show-terms></smc-ccb-text>\n                        </label>\n                    </smc-input-group>\n                    <smc-input-group data-edits=\"cool-checkbox\" data-eq=\"4\">\n                        <label>\n                            <input type=\"checkbox\" name=\"smc-agree2\" value=\"yes\" data-required=\"true\">\n                            <smc-ccb-tick></smc-ccb-tick>\n                            <smc-ccb-text>I also agree to the <smc-show-terms data-id=\"terms2\">secondary terms</smc-show-terms> as well</smc-ccb-text>\n                        </label>\n                    </smc-input-group>\n                </smc-cool-checkboxes>\n                <!-- End Cool Checkboxes -->\n                <input class=\"smc-button smc-animated smc-fadeInRight smc-animDelay10\" value=\"Save My Basket\" type=\"submit\">\n            </smc-option>\n\n            <!-- Closers (Both Need) -->\n            <smc-long-close class=\"smc-animated smc-fadeInUp smc-animDelay14\" data-engage-class=\"smc-engaged\">\n                <a data-close-type=\"long_close\" class=\"smc-link smc-closer\" href=\"#rdl\" data-engage-text=\"{text11}\" data-edits=\"text7,text11\" data-changes=\"smc-long-close a.smc-link|font-size,color,margin-top,margin-bottom\">{text7}</a>\n                <!-- Note - Redirect Link gets automatically rewritten, once clicked on the data-engage text and classes are applied -->\n            </smc-long-close>\n\n            <smc-close class=\"smc-closer\">\n                <a data-close-type=\"x_close\" class=\"smc-link\" href=\"#rdl\">✕</a><!-- Note - Redirect Link gets automatically rewritten -->\n            </smc-close>\n            \n\n            <!-- Success Message -->\n            <smc-success-message class=\"smc-animated smc-fadeIn\">\n                <smc-success-message-inner class=\"smc-animated smc-bounceInDown smc-animDelay1\">\n                    Perfect thank you!\n                    <smc-success-close>X</smc-success-close>\n                </smc-success-message-inner>    \n            </smc-success-message>\n            \n            <!-- CSS Loader -->\n            <smc-loader-bg data-theme=\"white\"><!-- white, black-->\n                <smc-loader-single></smc-loader-single><!-- single, double, pulse -->\n            </smc-loader-bg>\n \n            <!-- Copy to Clipboard Success Message -->\n            <smc-cp-msg>\"{vc}\" tu codigo ha sido copiado</smc-cp-msg>\n\n        </smc-overlay-inner>\n        <smc-shake-msg>\n            <i class=\"fa fa-mobile\" aria-hidden=\"true\"></i><br>\n            Shake To Reaveal Voucher\n        </smc-shake-msg>\n    </smc-overlay-outer>\n    \n    <!-- Safe close - Used when Autoscaling is turned on -->\n    <smc-close-safe class=\"smc-closer\">\n    \t<a data-close-type=\"x_close\" class=\"smc-link\" href=\"#rdl\">[close]</a><!-- Note - Redirect Link gets automatically rewritten -->\n    </smc-close-safe>\n</smc-bg>\n\n<!-- SmarterBar -->\n<smc-bar class=\"smc-animated smc-fadeInDown\">\n    <smc-bar-close>X</smc-bar-close>\n    <smc-bar-text>{smarterbar}</smc-bar-text>\n    <smc-handle>\n        <span class=\"smc-bar1\"></span>\n        <span class=\"smc-bar2\"></span>\n        <span class=\"smc-bar3\"></span>\n    </smc-handle>\n</smc-bar>\n\n<!-- Final Mesage Box -->\n<smc-final-message class=\"smc-animated smc-fadeInDown\">Thanks... your code is: {vc}<smc-final-message-close>X</smc-final-message-close></smc-final-message>","opt":""},"RD0001":{"css":"@import url(\"https://fonts.smct.co/GrandSlang-Roman/GrandSlang-Roman.css\");\r\n@import url(\"https://use.typekit.net/dpt0gct.css\");\r\n\r\nsmc-bg * {\r\n  font-family: \"dm-sans\", sans-serif;\r\n}\r\nsmc-overlay-inner {\r\n  --smc-mainBkg: #ffd814;\r\n  --smc-textColour: #000;\r\n  --smc-btnBkg: #fff;\r\n  --smc-btnText:#2a2827;\r\n  --smc-frameBorderRadius:2px;\r\n  --smc-btnBorderRadius: 999px;\r\n  --smc-btnFontSize: 12px;\r\n  --smc-btnPadding: 12px;\r\n}\r\nsmc-overlay-inner {\r\n  background-image: url('{content6}');\r\n  background-position: center;\r\n  background-size: cover;\r\n  width: 580px;\r\n  min-height: 300px;\r\n  padding-bottom: 0;\r\n  overflow: hidden;\r\n  border-radius: 2px;\r\n}\r\n\r\n/* Align the content Left */\r\nsmc-img-outer,\r\nsmc-text-outer,\r\nsmc-option,\r\nsmc-long-close {\r\n  width: 40%;\r\n  margin: 0 0 0 30px;\r\n}\r\n\r\n.smc-text1,\r\n.smc-text2,\r\n.smc-text3 {\r\n  font-size: 16px;\r\n  font-weight: 400;\r\n  margin: 12px auto;\r\n  text-align: center;\r\n  color: var(--smc-textColour);\r\n}\r\n\r\n.smc-text1,\r\n.smc-text3 {\r\n  opacity: 0.7;\r\n}\r\n\r\n.smc-text1 {\r\n  font-size: 38px;\r\n  font-weight: normal;\r\n  font-family:\"GrandSlang-Roman\", cursive;\r\n  margin: 55px auto auto auto;\r\n}\r\n\r\n.smc-button{\r\n  max-width: 130px;\r\n  margin: 25px auto auto auto;\r\n  border: 1.5px solid var(--smc-btnText);\r\n  background: var(--smc-btnBkg);\r\n  color: var(--smc-btnText);\r\n  font-size: var(--smc-btnFontSize);\r\n  font-weight: normal;\r\n  padding: var(--smc-btnPadding);\r\n  border-radius: var(--smc-btnBorderRadius);\r\n}\r\n.smc-button:hover{\r\n  background-color: var(--smc-btnText);\r\n  color: var(--smc-btnBkg);\r\n}\r\n\r\nsmc-close {\r\n  font-size: 14px;\r\n}\r\n\r\nsmc-close a.smc-link {\r\n  color: #000;\r\n}","html":"<!-- Overlay V4 Template -->\n<smc-bg class=\"smc-animated smc-fadeIn\">\n\t<smc-overlay-outer class=\"smc-animated smc-bounceInDown smc-animDelay2\"> <!--  data-animout=\"smc-bounceOutLeft\" --> \n        <smc-overlay-inner class=\"smc_clearfix\" data-bgtheme=\"dark\" data-changes=\"smc-overlay-inner|width,background-image,background-color\" data-edits=\"content6\"><!-- If the background is dark use this option -->\n\n            <!-- Images - You can add as many as you like -->\n            <smc-img-outer>\n                <smc-img class=\"smc-img1 smc-animated smc-bounceInDown smc-animDelay6\" data-changes=\".smc-img1|margin-top,margin-bottom,image-upload\" data-edits=\"content1\"><img src=\"{content1}\" alt=\"\"></smc-img>\n                <smc-img class=\"smc-img2 smc-animated smc-bounceInRight smc-animDelay8\" data-changes=\".smc-img2|margin-top,margin-bottom,image-upload\" data-edits=\"content2\"><img src=\"{content2}\" alt=\"\"></smc-img>\n                <smc-img class=\"smc-img3 smc-animated smc-bounceInRight smc-animDelay10\" data-changes=\".smc-img3|margin-top,margin-bottom,image-upload\" data-edits=\"content3\"><img src=\"{content3}\" alt=\"\"></smc-img>\n                <smc-img class=\"smc-img4 smc-animated smc-bounceInRight smc-animDelay12\" data-changes=\".smc-img4|margin-top,margin-bottom,image-upload\" data-edits=\"content4\"><img src=\"{content4}\" alt=\"\"></smc-img>\n            </smc-img-outer>\n            \n            <!-- Text Boxes - You can add as many as you like -->\n            <smc-text-outer>\n                <smc-text class=\"smc-text1 smc-animated smc-bounceInDown smc-animDelay4\" data-edits=\"text1\" data-changes=\".smc-text1|font-size,color,margin-top,margin-bottom\">{text1}</smc-text>\n                <smc-text class=\"smc-text2 smc-animated smc-bounceInRight smc-animDelay6\" data-edits=\"text2\" data-changes=\".smc-text2|font-size,color,margin-top,margin-bottom\">{text2}</smc-text>\n                <smc-text class=\"smc-text3 smc-animated smc-bounceInLeft smc-animDelay8\" data-edits=\"text3\" data-changes=\".smc-text3|font-size,color,margin-top,margin-bottom\">{text3}</smc-text>\n                <smc-text class=\"smc-text4 smc-animated smc-bounceInRight smc-animDelay10\" data-edits=\"text4\" data-changes=\".smc-text4|font-size,color,margin-top,margin-bottom\">{text4}</smc-text>\n            </smc-text-outer>\n            \n            <!-- Email Voucher Option -->\n            <smc-option class=\"smc-email\">\n                <smc-input-group><input class=\"smc-input smc-animated smc-fadeInLeft smc-animDelay8\" name=\"email\" autocomplete=\"smc-autocomplete\" data-required=\"true\" data-verify=\"email\" placeholder=\"ENTER YOUR EMAIL HERE\" type=\"text\"></smc-input-group>\n                <smc-input-group><input class=\"smc-button smc-animated smc-fadeInRight smc-animDelay10\" value=\"Email Voucher\" type=\"submit\"></smc-input-group>\n            </smc-option>\n            \n            <!-- Click To Reveal Option -->\n            <smc-option class=\"smc-clickToReveal\">\n          